def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [[0] * w for _ in range(h)]
    barrier = next((r for r, row in enumerate(grid) if row and all(v == 2 for v in row)), None)

    for r, row in enumerate(grid):
        for c, v in enumerate(row):
            if v == 2:
                out[r][c] = 2

    for r, row in enumerate(grid):
        for c, v in enumerate(row):
            if v != 4:
                continue
            if barrier is not None and 1 <= barrier - r <= 2:
                center_r = barrier - 1
                out[center_r][c] = 4
                for k in range(1, h):
                    rr = center_r - k
                    if rr < 0:
                        break
                    if c - k >= 0:
                        out[rr][c - k] = 4
                    if c + k < w:
                        out[rr][c + k] = 4
            else:
                rr = min(r + 1, h - 1)
                out[rr][c] = 4

    return out
